// Entry point. Dart starts at main(), like main.js in a Vue/Vite app.

import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_localizations/flutter_localizations.dart';

// Generated by `flutter gen-l10n` from lib/l10n/*.arb (not checked in).
import 'package:cometcast/l10n/app_localizations.dart';

import 'core/core_api.dart';
import 'core/rust_loader.dart';
import 'home_page.dart';
import 'settings.dart';

// Accent colour of the brand.
const Color cometAccent = Color(0xFF2D4A8A);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // Load the Rust core (libcc_ffi) before the first screen.
  await initRustCore();
  runApp(CometCastApp(
    core: const RustCoreApi(),
    // Development only: bind WebRTC to one local address, e.g. COMETCAST_UDP_BIND=127.0.0.1:0.
    settings: AppSettings(udpBind: _env('COMETCAST_UDP_BIND')),
  ));
}

String? _env(String name) {
  final v = Platform.environment[name];
  return (v == null || v.isEmpty) ? null : v;
}

/// Root widget (like App.vue). Pass [locale] to force a language (used by tests).
class CometCastApp extends StatelessWidget {
  CometCastApp(
      {super.key, this.locale, required this.core, AppSettings? settings})
      : settings = settings ?? AppSettings();

  final Locale? locale;

  /// The Rust core (or a fake in tests).
  final CoreApi core;

  /// Settings shared by the screens (server address).
  final AppSettings settings;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      // onGenerateTitle is used because the title needs translations.
      onGenerateTitle: (context) => AppLocalizations.of(context).appTitle,
      locale: locale, // null = follow the system language
      localizationsDelegates: const [
        AppLocalizations.delegate,
        GlobalMaterialLocalizations.delegate,
        GlobalWidgetsLocalizations.delegate,
        GlobalCupertinoLocalizations.delegate,
      ],
      supportedLocales: const [Locale('en'), Locale('de')],
      // Use the system language if supported, otherwise English.
      localeResolutionCallback: (deviceLocale, supported) {
        for (final l in supported) {
          if (l.languageCode == deviceLocale?.languageCode) return l;
        }
        return const Locale('en');
      },
      theme: ThemeData(
        useMaterial3: true,
        colorScheme: ColorScheme.fromSeed(seedColor: cometAccent),
      ),
      darkTheme: ThemeData(
        useMaterial3: true,
        colorScheme: ColorScheme.fromSeed(
          seedColor: cometAccent,
          brightness: Brightness.dark,
        ),
      ),
      themeMode: ThemeMode.system, // light/dark follows the system
      home: HomePage(core: core, settings: settings),
    );
  }
}
